import { FILE_MANAGER } from "./listView";
// Export dialogs (cURL/Python) and the sanitized-session dialog.
//
// The displayed text is generated by Rust and is exactly what the copy and the saved file receive.
// The UI does not build, edit or run the exported code.

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { bridge, type ExportPreview, type SanitizePreview, type SanitizeSaved, type SavedFile } from "./bridge";
import type { RequestRecord, SessionRecord } from "./types";
import { scriptProxyNotice, sessionExportProxyNotice } from "./proxyRules";

const bodyStateLabel: Record<string, string> = {
  captured: "captured",
  truncated: "truncated at capture",
  unavailable: "unavailable",
  empty: "empty",
  discarded: "discarded",
};

const verificationLabel: Record<string, string> = {
  verified: "headers verified",
  partial: "headers partially verified",
  unverified: "headers not verified",
};

function safeFileName(value: string): string {
  const cleaned = value.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "");
  return cleaned || "export";
}

function Modal({
  title,
  subtitle,
  onClose,
  children,
  footer,
  wide,
}: {
  title: string;
  subtitle?: string;
  onClose: () => void;
  children: React.ReactNode;
  footer?: React.ReactNode;
  wide?: boolean;
}) {
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        onClose();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  return (
    <div className="modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}>
      <div
        className={wide ? "modal modal-wide" : "modal"}
        role="dialog"
        aria-modal="true"
        aria-label={title}
      >
        <header className="modal-head">
          <div>
            <h2>{title}</h2>
            {subtitle && <p className="modal-sub">{subtitle}</p>}
          </div>
          <button className="icon-btn" onClick={onClose} title="Close (Esc)" aria-label="Close">
            ×
          </button>
        </header>
        <div className="modal-body">{children}</div>
        {footer && <footer className="modal-foot">{footer}</footer>}
      </div>
    </div>
  );
}

function WarningList({ warnings }: { warnings: { code: string; message: string }[] }) {
  if (warnings.length === 0) return null;
  return (
    <div className="export-block">
      <h3>
        Core warnings <span className="count">{warnings.length}</span>
      </h3>
      <ul className="export-list">
        {warnings.map((warning, index) => (
          <li key={`${warning.code}-${index}`}>
            <span className="mono chip-code">{warning.code}</span>
            <span>{warning.message}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

/**
 * Risk recorded in docs/08: `LogicalRequest.url` is that of the 1st attempt, but
 * body and headers are those of the last. On a 307/308 the export combines the initial
 * URL with the final body — equivalent to a replay that follows the redirect.
 */
export function replayRedirectWarning(request: RequestRecord): string | null {
  const attempts = request.attempts;
  if (attempts.length < 2) return null;
  const first = attempts[0];
  const last = attempts[attempts.length - 1];
  const preserving = attempts.slice(0, -1).some((attempt) => attempt.status === 307 || attempt.status === 308);
  if (!preserving || first.url === last.url) return null;
  return `The export uses ${first.url} (1st attempt) with the body and headers of the final attempt, which was sent to ${last.url} after the redirect ${attempts.find((a) => a.status === 307 || a.status === 308)?.status}. This is equivalent to a replay that follows the redirect; check the URL before reusing it.`;
}

export function ExportDialog({
  session,
  request,
  onClose,
}: {
  session: SessionRecord;
  request: RequestRecord;
  onClose: () => void;
}) {
  const sessionDir = session.sourcePath;
  const [format, setFormat] = useState<"curl" | "python" | "priming">("curl");
  const [annotate, setAnnotate] = useState(false);
  const [lenient, setLenient] = useState(false);
  const [preview, setPreview] = useState<ExportPreview | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [status, setStatus] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState<SavedFile | null>(null);
  const redirectWarning = replayRedirectWarning(request);
  const proxyNotice = scriptProxyNotice(session.capture?.proxy);

  useEffect(() => {
    if (!sessionDir) {
      setError("This session has no persisted folder; open a capture or import a file to export.");
      return;
    }
    let alive = true;
    setLoading(true);
    setError(null);
    setStatus(null);
    setSaved(null);
    setPreview(null);
    bridge
      .exportRequest(sessionDir, request.id, format, annotate, format === "priming" && lenient)
      .then((result) => {
        if (!alive) return;
        if (result.requestId !== request.id) {
          setError(`Generation returned request ${result.requestId}; expected ${request.id}. Generate again.`);
          return;
        }
        setPreview(result);
      })
      .catch((reason) => {
        if (alive) setError(String(reason));
      })
      .finally(() => {
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [format, annotate, lenient, request.id, sessionDir]);

  const copy = useCallback(async () => {
    if (!preview) return;
    const ok = await bridge.copyText(preview.text);
    setStatus(ok ? `${preview.format} text copied to the clipboard.` : "Could not copy.");
  }, [preview]);

  const save = useCallback(async () => {
    if (!preview) return;
    if (preview.requestId !== request.id) {
      setError("The selection changed while the preview was being generated. Close and reopen the export.");
      return;
    }
    setSaving(true);
    setError(null);
    setStatus(null);
    const name = `${safeFileName(request.id)}.${preview.format === "curl" ? "sh" : "py"}`;
    try {
      // The saved text is the same object shown in the preview; nothing is regenerated.
      const result = await bridge.saveExport(name, preview.text);
      if (!result) {
        setStatus("Save cancelled; nothing was written.");
        return;
      }
      setSaved(result);
      setStatus(`File saved (${result.bytes} bytes).`);
    } catch (reason) {
      setError(String(reason));
    } finally {
      setSaving(false);
    }
  }, [preview, request.id]);

  // The state comes from the session; the note below is the literal explanation from the core
  // (e.g.: "body not included: state Unavailable"). We do not rewrite the core's text
  // nor duplicate its conclusion.
  const bodyState = useMemo(() => {
    if (!preview) return null;
    return {
      label: bodyStateLabel[preview.bodyState] ?? preview.bodyState,
      note: preview.bodyNote?.trim() ?? null,
    };
  }, [preview]);

  return (
    <Modal
      title="Export request"
      subtitle={`${request.method} ${request.url}`}
      onClose={onClose}
      wide
      footer={
        <>
          <span className="modal-note">
            ScrapeLens does not run or resend the request. It may contain the session's cookies/credentials.
          </span>
          <span className="grow" />
          <button className="btn" onClick={() => void copy()} disabled={!preview || loading}>
            Copy
          </button>
          <button className="btn primary" onClick={() => void save()} disabled={!preview || loading || saving}>
            {saving ? "Saving…" : "Save…"}
          </button>
        </>
      }
    >
      <div className="export-tabs" role="tablist" aria-label="Export format">
        {(["curl", "python", "priming"] as const).map((id) => (
          <button
            key={id}
            role="tab"
            aria-selected={format === id}
            className={format === id ? "tab active" : "tab"}
            onClick={() => setFormat(id)}
          >
            {id === "curl" ? "cURL" : id === "python" ? "Python" : "Priming script"}
          </button>
        ))}
        <label className="annotate-opt" hidden={format === "priming"} title="Comments with the observed origin of each value; the generated command does not change">
          <input type="checkbox" checked={annotate} onChange={(e) => setAnnotate(e.target.checked)} /> annotate origins
        </label>
        {format === "priming" && (
          <label
            className="annotate-opt"
            title="Advanced: only values that look like identifiers, secrets or timestamps become parameters; the rest of the parts without origin stay literal. Off by default (strict mode)."
          >
            <input type="checkbox" checked={lenient} onChange={(e) => setLenient(e.target.checked)} /> lenient parts (advanced)
          </label>
        )}
        <span className="grow" />
        {preview && (
          <span className={`tag ${preview.headerVerification === "verified" ? "tag-real" : "tag-demo"}`}>
            {verificationLabel[preview.headerVerification] ?? preview.headerVerification}
          </span>
        )}
        {preview && <span className="tag">{preview.protocol.toUpperCase()}</span>}
      </div>

      {format === "priming" && preview && (
        <div className="notice notice-info">
          <span className="notice-icon">i</span>
          <span>
            {preview.adapter
              ? `Priming script with the protocol adapter's encoder (${preview.adapter}): claimed field lengths are recalculated in UTF-16, instead of swapping fragments.`
              : "Priming script without a protocol adapter: no claimed field; values are replaced by fragments."}
          </span>
        </div>
      )}

      <p className="export-disclaimer">
        The export reproduces the request at the HTTP level. It does <strong>not</strong> replicate TLS, JA3/JA4, frame
        order or the browser's HPACK.
      </p>

      {loading && <div className="notice notice-info"><span className="notice-icon">…</span><span>Generating export in Rust…</span></div>}
      {error && <div className="notice notice-error"><span className="notice-icon">!</span><span>{error}</span></div>}
      {status && <div className="notice notice-success"><span className="notice-icon">✓</span><span>{status}</span></div>}

      {preview && (
        <>
          {bodyState && (
            <div className="export-body-state">
              <span className="export-body-label">Body: {bodyState.label}</span>
              {bodyState.note && <span className="export-body-note">{bodyState.note}</span>}
            </div>
          )}
          <pre className="export-code" aria-label="Export preview">
            {preview.text}
          </pre>
          {preview.skippedHeaders.length > 0 && (
            <div className="export-block">
              <h3>
                Headers not exported <span className="count">{preview.skippedHeaders.length}</span>
              </h3>
              <p className="export-hint">
                The core omitted these headers because they cannot be safely represented (for example, values with
                CR/LF).
              </p>
              <div className="chip-row">
                {preview.skippedHeaders.map((name) => (
                  <span className="chip mono" key={name}>
                    {name}
                  </span>
                ))}
              </div>
            </div>
          )}
          <WarningList warnings={preview.warnings} />
          {redirectWarning && (
            <div className="body-flag flag-truncated" role="alert">
              <strong>Warning: 1st attempt URL differs from the final one</strong>
              <span>{redirectWarning}</span>
            </div>
          )}
          {proxyNotice && (
            <div className="body-flag flag-truncated" role="note" data-testid="export-proxy-notice">
              <strong>Not through the capture proxy</strong>
              <span>{proxyNotice}</span>
            </div>
          )}
          {saved && (
            <p className="export-saved mono" title={saved.path}>
              {saved.path}
            </p>
          )}
        </>
      )}

      {!sessionDir && !error && <p className="export-hint">Session without persisted folder.</p>}
    </Modal>
  );
}

export function SanitizeDialog({
  session,
  onClose,
  onOpened,
}: {
  session: SessionRecord;
  onClose: () => void;
  onOpened: (payload: Awaited<ReturnType<typeof bridge.openSessionAt>>) => void;
}) {
  const sessionDir = session.sourcePath;
  const [includeSensitive, setIncludeSensitive] = useState(false);
  const [destination, setDestination] = useState("");
  const previousSuggestion = useRef("");
  const [preview, setPreview] = useState<SanitizePreview | null>(null);
  const [saved, setSaved] = useState<SanitizeSaved | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [status, setStatus] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!sessionDir) {
      setError("This session has no persisted folder; sanitizing requires the session's files.");
      return;
    }
    let alive = true;
    setLoading(true);
    setError(null);
    bridge
      .previewSanitized(sessionDir, includeSensitive)
      .then((result) => {
        if (alive) {
          const previous = previousSuggestion.current;
          setDestination((current) => !current || current === previous ? result.suggestedDestination : current);
          previousSuggestion.current = result.suggestedDestination;
          setPreview(result);
        }
      })
      .catch((reason) => {
        if (alive) setError(String(reason));
      })
      .finally(() => {
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [sessionDir, includeSensitive]);

  const save = useCallback(async () => {
    if (!sessionDir || !preview || loading || !!preview.includeSensitive !== includeSensitive || !destination.trim()) return;
    setSaving(true);
    setError(null);
    setStatus(null);
    try {
      const result = await bridge.saveSanitized(sessionDir, destination.trim(), includeSensitive);
      if (!result) {
        setStatus("Save cancelled; the original session was not changed.");
        return;
      }
      setSaved(result);
      setStatus(includeSensitive ? "Full capture saved with sensitive data in a private folder (0700/0600)." : "Sanitized session saved in a new private folder (0700/0600).");
    } catch (reason) {
      setError(String(reason));
    } finally {
      setSaving(false);
    }
  }, [preview, sessionDir, destination, includeSensitive, loading]);

  const open = useCallback(async () => {
    if (!saved) return;
    try {
      const payload = await bridge.openSessionAt(saved.path);
      onOpened(payload);
      onClose();
    } catch (reason) {
      setError(String(reason));
    }
  }, [onClose, onOpened, saved]);

  return (
    <Modal
      title="Export / Sanitize entire session"
      subtitle={session.id}
      onClose={onClose}
      wide
      footer={
        <>
          <span className="modal-note">
            {saved ? "The origin remains intact." : "Nothing is written until you confirm the destination in the native dialog."}
          </span>
          <span className="grow" />
          <button className="btn" onClick={onClose}>
            Close
          </button>
          {saved ? (
            <>
              <button className="btn" onClick={() => void bridge.revealPath(saved.path)}>
                Show in {FILE_MANAGER}
              </button>
              <button className="btn primary" onClick={() => void open()}>
                {saved.includeSensitive ? "Open full capture" : "Open sanitized session"}
              </button>
            </>
          ) : (
            <button className="btn primary" onClick={() => void save()} disabled={!preview || loading || saving || !!preview.includeSensitive !== includeSensitive || !destination.trim()}>
              {saving ? "Writing…" : includeSensitive ? "Export full capture" : "Save sanitized copy"}
            </button>
          )}
        </>
      }
    >
      {sessionExportProxyNotice(session.capture?.proxy) && (
        <div className="body-flag flag-truncated" role="note" data-testid="export-proxy-notice">
          <strong>Captured through a proxy</strong>
          <span>{sessionExportProxyNotice(session.capture?.proxy)}</span>
        </div>
      )}
      <label className="export-sensitive-option">
        <input type="checkbox" data-testid="sanitize-include-sensitive"
          checked={includeSensitive} disabled={saving || !!saved}
          onChange={(event) => {
            setIncludeSensitive(event.target.checked);
            setStatus(null);
          }} />
        Include sensitive data (export the full capture without redacting cookies, headers, bodies and raw events)
      </label>
      {includeSensitive && <div className="export-warning" role="alert">
        The full capture will contain credentials, cookies, tokens, raw bodies and raw artifacts
        (cdp-events.jsonl, netlog.json and cdp-bodies.jsonl, when present) without redaction.
      </div>}
      {!includeSensitive && <p className="export-disclaimer">
        Uses the core's conservative policy (<span className="mono">keep_raw_events=false</span>): redacts headers,
        cookies, tokens in URLs and sensitive bodies, and omits attachments that cannot be sanitized safely. The
        origin is never changed.
      </p>}
      {!saved && <label className="export-destination">
        Suggested destination (confirm in the native dialog)
        <input className="start-url-input mono" aria-label="Export destination" value={destination}
          disabled={loading || saving} onChange={(event) => setDestination(event.target.value)} />
      </label>}

      {loading && <div className="notice notice-info"><span className="notice-icon">…</span><span>Calculating the preview in Rust…</span></div>}
      {error && <div className="notice notice-error"><span className="notice-icon">!</span><span>{error}</span></div>}
      {status && <div className="notice notice-success"><span className="notice-icon">✓</span><span>{status}</span></div>}

      {preview && (
        <>
          <div className="stat-row">
            <div className="stat">
              <span className="stat-num">{preview.requests}</span>
              <span className="stat-label">requests</span>
            </div>
            <div className="stat">
              <span className="stat-num">{preview.totalRedactions}</span>
              <span className="stat-label">redactions</span>
            </div>
            <div className="stat">
              <span className="stat-num">{preview.attachmentsKept}</span>
              <span className="stat-label">attachments kept</span>
            </div>
            <div className="stat">
              <span className="stat-num">{preview.omittedAttachments.length}</span>
              <span className="stat-label">attachments omitted</span>
            </div>
          </div>

          <div className="export-block">
            {preview.warnings.some((w) => w.code === "sanitize.business_field_unmatched") && (
              <div className="body-flag flag-truncated" role="alert">
                <strong>Business field without a value in the expected format</strong>
                {preview.warnings
                  .filter((w) => w.code === "sanitize.business_field_unmatched")
                  .map((w, index) => (
                    <span key={index}>{w.message}</span>
                  ))}
                <span>These values were NOT silently redacted: check them before sharing.</span>
              </div>
            )}
            <h3>Redactions by origin</h3>
            {preview.redactions.length === 0 ? (
              <p className="export-hint">
                {includeSensitive ? "Data preserved in full; no redaction applied." : "No redactions counted. This does not prove the session is free of credentials: sanitization is heuristic."}
              </p>
            ) : (
              <ul className="redaction-list">
                {preview.redactions.map((item) => (
                  <li key={item.key}>
                    <span className="mono">{item.key}</span>
                    {item.key.startsWith("business:") && (
                      <span className="dim"> business field ({item.key.slice("business:".length)}), value not shown</span>
                    )}
                    <span className="count">{item.count}</span>
                  </li>
                ))}
              </ul>
            )}
          </div>

          {preview.omittedAttachments.length > 0 && (
            <div className="export-block">
              <h3>
                Attachments omitted <span className="count">{preview.omittedAttachments.length}</span>
              </h3>
              <p className="export-hint">
                Binaries, unstructured text or invalid JSON are omitted with a warning instead of copied.
              </p>
              <div className="chip-row">
                {preview.omittedAttachments.map((name) => (
                  <span className="chip mono" key={name}>
                    {name}
                  </span>
                ))}
              </div>
            </div>
          )}

          {preview.rawArtifactsDropped.length > 0 && (
            <div className="export-block">
              <h3>Raw artifacts not copied</h3>
              <div className="chip-row">
                {preview.rawArtifactsDropped.map((name) => (
                  <span className="chip mono" key={name}>
                    {name}
                  </span>
                ))}
              </div>
            </div>
          )}

          {!!preview.rawArtifactsKept?.length && <div className="export-block">
            <h3>Raw artifacts included</h3>
            <div className="chip-row">{preview.rawArtifactsKept.map((name) => <span className="chip mono" key={name}>{name}</span>)}</div>
          </div>}
          <WarningList warnings={preview.warnings} />

          <p className="export-hint mono">suggested destination: {preview.suggestedDestination}</p>

          {saved && (
            <div className="export-block">
              <h3>Saved result</h3>
              <ul className="redaction-list">
                <li>
                  <span className="mono">{saved.path}</span>
                </li>
                <li>
                  <span>requests</span>
                  <span className="count">{saved.requests}</span>
                </li>
                <li>
                  <span>redactions</span>
                  <span className="count">{saved.totalRedactions}</span>
                </li>
                <li>
                  <span>attachments kept</span>
                  <span className="count">{saved.attachmentsKept}</span>
                </li>
                <li>
                  <span>attachments omitted</span>
                  <span className="count">{saved.omittedAttachments.length}</span>
                </li>
                <li>
                  <span>session.json</span>
                  <span className="count">{saved.sessionBytes} B</span>
                </li>
              </ul>
            </div>
          )}
        </>
      )}
    </Modal>
  );
}
